/* Northern Lights Theme - Auto-generated from tweakcn */

/* Light mode */
[data-theme="northern-lights-light"] {
  --background: hsl(300 0% 97.37%);
  --foreground: hsl(0 0% 19.89%);
  --card: hsl(300 50% 100%);
  --card-foreground: hsl(0 0% 19.89%);
  --popover: hsl(300 50% 100%);
  --popover-foreground: hsl(0 0% 19.89%);
  --primary: hsl(138.99 49.47% 44.05%);
  --primary-foreground: hsl(300 50% 100%);
  --secondary: hsl(218.54 76.87% 65.45%);
  --secondary-foreground: hsl(300 50% 100%);
  --muted: hsl(50.38 27.52% 81.24%);
  --muted-foreground: hsl(320 0% 43.34%);
  --accent: hsl(189.59 83.14% 66.89%);
  --accent-foreground: hsl(0 0% 19.89%);
  --destructive: hsl(359.91 86.11% 60.55%);
  --destructive-foreground: hsl(300 50% 100%);
  --border: hsl(340 0% 83.14%);
  --input: hsl(340 0% 83.14%);
  --ring: hsl(138.99 49.47% 44.05%);
  --chart-1: hsl(138.99 49.47% 44.05%);
  --chart-2: hsl(218.54 76.87% 65.45%);
  --chart-3: hsl(189.59 83.14% 66.89%);
  --chart-4: hsl(207.26 44.15% 49.24%);
  --chart-5: hsl(138.65 69.33% 34.68%);
  --radius: 0.5rem;
  --sidebar: hsl(300 0% 97.37%);
  --sidebar-foreground: hsl(0 0% 19.89%);
  --sidebar-primary: hsl(138.99 49.47% 44.05%);
  --sidebar-primary-foreground: hsl(300 50% 100%);
  --sidebar-accent: hsl(189.59 83.14% 66.89%);
  --sidebar-accent-foreground: hsl(0 0% 19.89%);
  --sidebar-border: hsl(340 0% 83.14%);
  --sidebar-ring: hsl(138.99 49.47% 44.05%);
  --font-sans: Plus Jakarta Sans, sans-serif;
  --font-serif: Source Serif 4, serif;
  --font-mono: JetBrains Mono, monospace;
  --shadow-color: hsl(0 0% 0%);
  --shadow-opacity: 0.1;
  --shadow-blur: 3px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0;
  --shadow-offset-y: 1px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
  --shadow-xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
  --shadow-sm:
    0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 1px 2px -1px hsl(0 0% 0% / 0.1);
  --shadow: 0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 1px 2px -1px hsl(0 0% 0% / 0.1);
  --shadow-md:
    0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 2px 4px -1px hsl(0 0% 0% / 0.1);
  --shadow-lg:
    0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 4px 6px -1px hsl(0 0% 0% / 0.1);
  --shadow-xl:
    0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 8px 10px -1px hsl(0 0% 0% / 0.1);
  --shadow-2xl: 0 1px 3px 0px hsl(0 0% 0% / 0.25);
  --tracking-normal: 0em;
}

